INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das hierarchische Modell immer baumartig strukturiert?', 2, '[{"text": "Ja", "correct": true, "because": "Parent-Child-Beziehungen"}, {"text": "Nein", "correct": false, "because": "Definiert durch Hierarchie"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für mich bei einem hierarchischen Modell entscheidend?', 3, '[{"text": "Eindeutige Eltern-Kind-Beziehungen", "correct": true, "because": "Definiert Struktur"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Sekundär"}, {"text": "Schnelle Installation", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein hierarchisches Modell?', 5, '[{"text": "Ein Elternteil pro Kind", "correct": true, "because": "Strenge Hierarchie"}, {"text": "Baumstruktur", "correct": true, "because": "Visuelle Darstellung"}, {"text": "Viele-zu-viele-Beziehungen", "correct": false, "because": "Nur Netzwerkmodell"}, {"text": "Flache Struktur", "correct": false, "because": "Gegenteil von Hierarchie"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Modell ist baumartig. b) Es erlaubt mehrere Eltern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ein Elternteil pro Kind"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim hierarchischen Modell?', 4, '[{"text": "Eltern-Kind-Beziehungen", "correct": false, "because": "Kern des Modells"}, {"text": "Hierarchische Ordnung", "correct": false, "because": "Definiert Struktur"}, {"text": "Farbcodierung", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das hierarchische Modell flexibel ist?', 2, '[{"text": "Nein", "correct": true, "because": "Strikte Struktur"}, {"text": "Ja", "correct": false, "because": "Wenig Anpassungsfähig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur wähle ich für ein hierarchisches Modell?', 3, '[{"text": "Baum", "correct": true, "because": "Repräsentiert Hierarchie"}, {"text": "Tabelle", "correct": false, "because": "Relationaler Ansatz"}, {"text": "Netzwerk", "correct": false, "because": "Anderes Modell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet mir das hierarchische Modell?', 5, '[{"text": "Einfache Navigation", "correct": true, "because": "Klare Pfade"}, {"text": "Schnelle Abfragen bei Hierarchie", "correct": true, "because": "Struktur unterstützt"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Eher starr"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Es ist baumartig. b) Es unterstützt viele-zu-viele-Beziehungen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Netzwerkmodell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein hierarchisches Modell?', 4, '[{"text": "Eltern-Kind-Struktur", "correct": false, "because": "Kernfeature"}, {"text": "Hierarchische Tiefe", "correct": false, "because": "Definiert Ebenen"}, {"text": "Flache Tabellen", "correct": true, "because": "Relationaler Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das hierarchische Modell für komplexe Beziehungen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Beschränkt auf 1:n"}, {"text": "Ja", "correct": false, "because": "Einfache Hierarchien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen das Modell effektiv?', 4, '[{"text": "Klare Hierarchie", "correct": true, "because": "Einfache Struktur"}, {"text": "Eindeutige Pfade", "correct": true, "because": "Schnelle Zugriffe"}, {"text": "Viele-zu-viele-Links", "correct": false, "because": "Nicht unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Modell nur für kleine Datenbanken ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Skalierbar bei Hierarchie"}, {"text": "Ja", "correct": false, "because": "Größe nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim hierarchischen Modell?', 3, '[{"text": "Strukturierte Ordnung", "correct": true, "because": "Definiert Modell"}, {"text": "Schnelle Änderungen", "correct": false, "because": "Schwierig anzupassen"}, {"text": "Minimale Tiefe", "correct": false, "because": "Tiefe variabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es hat eine Baumstruktur. b) Es ist relational.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht relational"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einschränkungen hat das hierarchische Modell?', 5, '[{"text": "Nur ein Elternteil", "correct": true, "because": "Strikte 1:n-Beziehung"}, {"text": "Schwere Änderungen", "correct": true, "because": "Struktur starr"}, {"text": "Hohe Speicherlast", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim hierarchischen Modell unwichtig?', 3, '[{"text": "Eltern-Kind-Links", "correct": false, "because": "Kern des Modells"}, {"text": "Baumtiefe", "correct": false, "because": "Definiert Ebenen"}, {"text": "Tabellenlayout", "correct": true, "because": "Relationaler Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt das Modell mehrere Eltern pro Kind?', 3, '[{"text": "Nein", "correct": true, "because": "Nur ein Elternteil erlaubt"}, {"text": "Ja", "correct": false, "because": "Netzwerkmodell erlaubt dies"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das hierarchische Modell für Dateisysteme geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Ordnerstruktur ähnlich"}, {"text": "Nein", "correct": false, "because": "Passend für Hierarchien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendung passt zum hierarchischen Modell?', 4, '[{"text": "Organisationsstruktur", "correct": true, "because": "Klare Hierarchie"}, {"text": "Soziale Netzwerke", "correct": false, "because": "Viele-zu-viele-Beziehungen"}, {"text": "Tabellenkalkulation", "correct": false, "because": "Flache Struktur"}]');
